import{_ as r,C as d,o,c as n,a5 as i,b as l,w as t,a as s,E as h,a6 as p,j as E}from"./chunks/framework.BEZBAInb.js";const A=JSON.parse('{"title":"会話データ","description":"","frontmatter":{"title":"会話データ","order":1},"headers":[],"relativePath":"ja/2.4/tutorial/core/shot-and-dialogue.md","filePath":"ja/2.4/tutorial/core/shot-and-dialogue.md","lastUpdated":1788455378000}'),D={name:"ja/2.4/tutorial/core/shot-and-dialogue.md"};function _(c,a,u,K,S,N){const e=d("Mermaid");return o(),n("div",null,[a[1]||(a[1]=i('<h1 id="knd-shot-と-knd-dialogue" tabindex="-1">KND_Shot と KND_Dialogue <a class="header-anchor" href="#knd-shot-と-knd-dialogue" aria-label="Permalink to &quot;KND_Shot と KND_Dialogue&quot;">​</a></h1><h2 id="はじめに" tabindex="-1">はじめに <a class="header-anchor" href="#はじめに" aria-label="Permalink to &quot;はじめに&quot;">​</a></h2><p>この章では、Konado の 2 つのコアクラスである KND_Shot と KND_Dialogue を紹介します。これらは Konado の中心となるクラスで、会話ショットと会話を表します。Konado のアーキテクチャを深く理解したい場合、この 2 つのクラスを理解することは非常に重要です。十分に理解したうえで、必要に応じて拡張や変更を行えます。</p><h2 id="knd-shot" tabindex="-1">KND_Shot <a class="header-anchor" href="#knd-shot" aria-label="Permalink to &quot;KND_Shot&quot;">​</a></h2><h3 id="定義" tabindex="-1">定義 <a class="header-anchor" href="#定義" aria-label="Permalink to &quot;定義&quot;">​</a></h3><p>KND_Shot は Konado のコアクラスであり、1 つの会話ショットを表します。</p><p>ショットは映像やアニメーション制作における基本概念で、連続した画面を表し、通常は一連のフレームを含みます。ここでは、KND_Shot クラスは一連の会話を含む会話ショットを表します。</p><p>本にたとえるなら、ショットは小さな章であり、会話ショットはその小さな章の中の会話です。</p><p>KND_Shot は、散らばった KND_Dialogue データオブジェクトを整理し、一定の順序で並べることで、再生時に指定された順序どおりに再生できるようにします。</p><p>ただし映画のショットとは異なり、KND_Shot は必ずしも連続した線形ストーリーを表すわけではありません。複数の branch 分岐で構成される場合があり、それぞれの分岐が一連の会話を含み、choice と組み合わせることで複数選択の分岐を実現し、ユーザーに異なる会話経路を選ばせることができます。</p><h3 id="knd-shot-と-konadoscript-の関係" tabindex="-1">KND_Shot と KonadoScript の関係 <a class="header-anchor" href="#knd-shot-と-konadoscript-の関係" aria-label="Permalink to &quot;KND_Shot と KonadoScript の関係&quot;">​</a></h3><p>使用していると分かるように、通常 KND_Shot を手動で作成する必要はありません。KonadoScript によって自動的に作成され、データも自動更新されます。これは、独自の KonadoScript 構文と KonadoScript パーサーを使用してスクリプトファイルを解析し、ソースファイルの各行を KND_Dialogue オブジェクトに変換し、一定の規則に従って KND_Shot オブジェクトへ整理するためです。</p><p>フローチャートで表すと、KonadoScript から複数の KND_Dialogue を経て KND_Shot へ至る流れはおおよそ次のようになります。</p>',13)),(o(),l(p,null,{default:t(()=>[h(e,{id:"mermaid-39",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5B%22KonadoScript%E3%82%BD%E3%83%BC%E3%82%B9%E3%83%95%E3%82%A1%E3%82%A4%E3%83%AB%22%5D%20--%3E%20B%5B%22%E3%83%91%E3%83%BC%E3%82%B5%E3%83%BC%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22KND_Dialogue%E3%82%AA%E3%83%96%E3%82%B8%E3%82%A7%E3%82%AF%E3%83%88%E3%82%92%E7%94%9F%E6%88%90%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22%E8%A6%8F%E5%89%87%E3%81%AB%E5%BE%93%E3%81%A3%E3%81%A6%E6%95%B4%E7%90%86%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%22KND_Shot%E3%82%92%E8%87%AA%E5%8B%95%E4%BD%9C%E6%88%90%2F%E6%9B%B4%E6%96%B0%22%5D%0A%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=E("p",null,"KonadoScript の解析過程について詳しく知りたい場合は、KonadoScript の関連ドキュメントとパーサーのソースコードを参照してください。",-1))])}const m=r(D,[["render",_]]);export{A as __pageData,m as default};
